python -I - <<'PY'
import pandas as pd
from decimal import Decimal
from pandas import Timestamp
print('pandas', pd.__version__)
try:
    import pyarrow as pa
    print('pyarrow available', pa.__version__)
except Exception as e:
    print('pyarrow import failed:', type(e).__name__, e)

# Try to construct reported values; capture exceptions as strings.

def safe_call(fn):
    try:
        v = fn()
        return ('ok', v)
    except Exception as e:
        return ('err', f'{type(e).__name__}: {e}')

from pandas.core.dtypes.dtypes import ArrowDtype

def ex1():
    return pd.array([Timestamp('2016-01-02 03:04:05'), Decimal('NaN')], dtype=ArrowDtype('timestamp[us]'))

print('ex1', safe_call(ex1))

# Ex2/3: try to create arrow-backed series; if no pyarrow, record the error.

def ex2():
    return pd.Series([Timestamp('2025-07-03 18:10')], dtype='timestamp[ns, US/Eastern][pyarrow]')[0]

print('ex2', safe_call(ex2))


def ex3():
    a = pd.Series([Timestamp('2025-07-03 18:10')], dtype='timestamp[ns, US/Eastern][pyarrow]')
    b = pd.Series([Timestamp('2025-07-03 18:10')], dtype='datetime64[ns, US/Eastern]').convert_dtypes(dtype_backend='pyarrow')
    import pandas._testing as tm
    tm.assert_series_equal(a, b)
    return 'assert_passed'

print('ex3', safe_call(ex3))
PY

